function makeRecipe(cca3: string, [method, keys]: RecipeSpec): CountryRecipe {
  const cuisine = COUNTRY_CUISINES[cca3];
  if (!cuisine) throw new Error(`Unknown recipe country ${cca3}`);
  const definingAction = COUNTRY_DEFINING_ACTIONS[cca3];
  if (!definingAction) throw new Error(`Missing defining action for ${cca3}`);
  const ingredients: Localized[] = keys.map((key) => ({ en: INGREDIENTS[key][0], de: INGREDIENTS[key][1] }));
  const custom = CUSTOM_RECIPES[cca3];
  if (custom) {
    const steps = [...custom.steps];
    const english = steps.map((step) => step.en).join(" ").toLowerCase();
    if (cuisine.diet === "meat" && !/completely[\s\S]*thermometer/.test(english)) steps.splice(steps.length - 1, 0, SAFETY.meat);
    if (cuisine.diet === "fish" && !/fully[\s\S]*safe-temperature/.test(english)) steps.splice(steps.length - 1, 0, SAFETY.fish);
    return { cca3, definingAction, ingredients: custom.ingredients, steps: [definingAction, ...steps], ...(custom.note ? { note: custom.note } : {}) };
  }
  ingredients.push(...methodExtras(method, keys));
  ingredients.push(pantryFor(cca3, keys));
  const steps = concreteSteps(method, ingredients, cuisine.dish, keys);
  if (cuisine.diet === "meat" || cuisine.diet === "fish") steps.splice(steps.length - 1, 0, SAFETY[cuisine.diet]);
  const hazardous = keys.includes("cassava") || keys.includes("ackee");
  return {
    cca3,
    definingAction,
    ingredients,
    steps: [definingAction, ...steps],
    ...(hazardous ? { note: { en:"Use only the commercially prepared ingredient specified above and follow its package directions; do not substitute raw, home-processed produce.", de:"Nur die oben angegebene handelsüblich vorbereitete Zutat verwenden und die Packungsanleitung befolgen; nicht durch rohe, selbst verarbeitete Ware ersetzen." } } : {}),
  };
}

export const COUNTRY_RECIPES: Record<string, CountryRecipe> = Object.fromEntries(
  Object.entries(specs).map(([cca3, spec]) => [cca3, makeRecipe(cca3, spec)])
);

export function getCountryRecipe(cca3: string): CountryRecipe | null {
  return COUNTRY_RECIPES[cca3] ?? null;
}
